'use client';

import {
  Check,
  FileCheck2,
  LoaderCircle,
  Search,
  UserRound,
} from 'lucide-react';
import { useMemo, useState } from 'react';

import type { Customer } from '@/lib/customer';
import { currencyDisplay, currencyOptions } from '@/lib/customer';
import {
  documentTabs,
  type DocumentNature,
  type DocumentTab,
} from '@/lib/document';
import { formatJalaliDate, normalizeDigits } from '@/lib/jalali';

type AmountField = 'goldAmount' | 'silverAmount' | 'platinumAmount' | 'rialAmount' | 'foreignAmount' | 'tertiaryAmount';
type DetailState = Record<string, string>;

const amountFields: Array<{ id: AmountField; label: string; unit: string }> = [
  { id: 'goldAmount', label: 'طلا', unit: 'گرم' },
  { id: 'silverAmount', label: 'نقره', unit: 'گرم' },
  { id: 'platinumAmount', label: 'پلاتین', unit: 'گرم' },
  { id: 'rialAmount', label: 'ریال', unit: 'ریال' },
  { id: 'foreignAmount', label: 'ارز دوم', unit: 'واحد' },
  { id: 'tertiaryAmount', label: 'ارز سوم', unit: 'واحد' },
];

const operationOptions: Record<DocumentTab, Array<[string, string]>> = {
  general: [['general', 'سند عمومی']],
  goods: [['purchase', 'خرید کالا'], ['sale', 'فروش کالا'], ['return', 'برگشت کالا']],
  currency: [['exchange', 'خرید و فروش ارز'], ['receipt', 'دریافت ارز'], ['payment', 'پرداخت ارز']],
  'stone-main': [['stone-main', 'سنگ مرکزی']],
  base: [['base', 'پایه / آبشده']],
  stone: [['stone', 'سنگ و نگین']],
  expense: [['expense', 'هزینه']],
  coin: [['coin', 'سکه']],
  'our-claim': [['claim', 'طلب ما']],
  bank: [['bank', 'حساب بانکی']],
  'cash-conversion': [['conversion', 'تبدیل وجه']],
  'gold-sale': [['gold-sale', 'فروش طلا']],
  check: [['check', 'چک']],
  cash: [['cash', 'وجه نقد']],
  itak: [['itak', 'ایتک']],
  workmanship: [['workmanship', 'کارساخت / اجرت']],
  'raw-gold': [['raw-gold', 'طلای خام']],
  other: [['other', 'سایر']],
};

export default function DocumentForm({
  customers,
  nextDocumentNumber,
}: {
  customers: Customer[];
  nextDocumentNumber: number;
}) {
  const [customerQuery, setCustomerQuery] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [documentNature, setDocumentNature] = useState<DocumentNature>('received');
  const [documentTab, setDocumentTab] = useState<DocumentTab>('general');
  const [documentSubType, setDocumentSubType] = useState('general');
  const [documentNumber, setDocumentNumber] = useState(String(nextDocumentNumber));
  const [documentDateJalali, setDocumentDateJalali] = useState(formatJalaliDate());
  const [description, setDescription] = useState('');
  const [settlementMethod, setSettlementMethod] = useState('mixed');
  const [balanceSource, setBalanceSource] = useState('current');
  const [amounts, setAmounts] = useState<Record<AmountField, string>>({
    goldAmount: '',
    silverAmount: '',
    platinumAmount: '',
    rialAmount: '',
    foreignAmount: '',
    tertiaryAmount: '',
  });
  const [details, setDetails] = useState<DetailState>({});
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const selectedCustomer = customers.find((customer) => customer.id === selectedCustomerId);
  const suggestions = useMemo(() => {
    const query = customerQuery.trim().toLocaleLowerCase();
    if (!query || selectedCustomer) return [];
    return customers
      .filter((customer) =>
        `${customer.name} ${customer.customerCode} ${customer.phone1}`
          .toLocaleLowerCase()
          .includes(query),
      )
      .slice(0, 8);
  }, [customerQuery, customers, selectedCustomer]);

  function chooseCustomer(customer: Customer) {
    setSelectedCustomerId(customer.id);
    setCustomerQuery(`${customer.customerCode} - ${customer.name}`);
  }

  function updateAmount(field: AmountField, value: string) {
    setAmounts((current) => ({ ...current, [field]: value }));
  }

  function updateDetail(field: string, value: string) {
    setDetails((current) => ({ ...current, [field]: value }));
  }

  function selectTab(tab: DocumentTab) {
    setDocumentTab(tab);
    setDocumentSubType(operationOptions[tab][0]?.[0] ?? 'general');
  }

  async function save(andNew = false) {
    setSaving(true);
    setMessage('');
    setErrorMessage('');

    const typedCode = Number(normalizeDigits(customerQuery).replace(/[^\d]/g, ''));
    const codeCustomer = Number.isInteger(typedCode) && typedCode > 0
      ? customers.find((customer) => customer.customerCode === typedCode)
      : undefined;
    const customerIdToSave = selectedCustomerId || codeCustomer?.id || '';

    if (!customerIdToSave) {
      setErrorMessage('ابتدا نام یا کد طرف‌حساب را انتخاب کنید.');
      setSaving(false);
      return;
    }

    try {
      const response = await fetch('/api/documents', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          customerId: customerIdToSave,
          documentNature,
          documentTab,
          documentSubType,
          documentNumber,
          documentDateJalali,
          description,
          settlementMethod,
          balanceSource,
          ...amounts,
          documentDetails: details,
        }),
      });
      const data = (await response.json().catch(() => null)) as
        | { message?: string; registeredAt?: string }
        | null;

      if (!response.ok) {
        setErrorMessage(data?.message ?? 'ثبت سند انجام نشد.');
        return;
      }

      setMessage(
        `سند شماره ${documentNumber} با موفقیت ثبت شد${data?.registeredAt
          ? `؛ زمان ثبت ${formatRegisteredAt(data.registeredAt)}`
          : ''}.`,
      );

      if (andNew) {
        setCustomerQuery('');
        setSelectedCustomerId('');
        setDescription('');
        setDetails({});
        setAmounts({
          goldAmount: '',
          silverAmount: '',
          platinumAmount: '',
          rialAmount: '',
          foreignAmount: '',
          tertiaryAmount: '',
        });
        setDocumentNumber(String(Number(documentNumber) + 1));
      }
    } catch {
      setErrorMessage('ارتباط با سرور برقرار نشد.');
    } finally {
      setSaving(false);
    }
  }

  const foreignLabel = selectedCustomer
    ? currencyDisplay(selectedCustomer.secondaryCurrency, selectedCustomer.secondaryCurrencySymbol)
    : 'ارز دوم';
  const tertiaryLabel = selectedCustomer
    ? currencyDisplay(selectedCustomer.tertiaryCurrency, selectedCustomer.tertiaryCurrencySymbol)
    : 'ارز سوم';

  return (
    <div className="document-form-page">
      <div className="dashboard-page-heading">
        <div>
          <p className="eyebrow">دفتر اسناد</p>
          <h1>ثبت سند جدید</h1>
          <p>سند دریافتی یا پرداختی را برای طرف‌حساب انتخاب و در دفتر ثبت کنید.</p>
        </div>
        <span className="document-current-time">تاریخ امروز: {formatJalaliDate()}</span>
      </div>

      {message ? <p className="account-message"><Check size={15} />{message}</p> : null}
      {errorMessage ? <p className="form-error">{errorMessage}</p> : null}

      <section className="dashboard-panel document-account-panel">
        <div className="account-panel-heading">
          <div>
            <p className="eyebrow">مشخصات حساب</p>
            <h2>انتخاب طرف‌حساب</h2>
          </div>
          {selectedCustomer ? (
            <span className="customer-code-badge">کد حساب {selectedCustomer.customerCode}</span>
          ) : null}
        </div>
        <div className="document-account-search-row">
          <label className="account-field document-account-search-field">
            <span>نام یا کد حساب</span>
            <div className="gooey-search document-search-shell">
              <Search size={16} />
              <input
                value={customerQuery}
                onChange={(event) => {
                  setCustomerQuery(event.target.value);
                  if (selectedCustomerId) setSelectedCustomerId('');
                }}
                placeholder="نام طرف‌حساب یا کد حساب را جستجو کنید..."
              />
            </div>
            {suggestions.length ? (
              <div className="document-customer-suggestions">
                {suggestions.map((customer) => (
                  <button type="button" key={customer.id} onClick={() => chooseCustomer(customer)}>
                    <span className="document-suggestion-avatar">
                      {customer.name.charAt(0)}
                    </span>
                    <span>
                      <strong>{customer.name}</strong>
                      <small>کد {customer.customerCode} {customer.phone1 ? `· ${customer.phone1}` : ''}</small>
                    </span>
                  </button>
                ))}
              </div>
            ) : null}
          </label>
          {selectedCustomer ? (
            <div className="document-selected-customer">
              <span className="document-suggestion-avatar"><UserRound size={16} /></span>
              <div>
                <strong>{selectedCustomer.name}</strong>
                <small>{selectedCustomer.gender === 'female' ? 'خانم' : selectedCustomer.gender === 'male' ? 'آقا' : 'طرف‌حساب'} · کد {selectedCustomer.customerCode}</small>
              </div>
              <button type="button" onClick={() => { setSelectedCustomerId(''); setCustomerQuery(''); }}>
                تغییر
              </button>
            </div>
          ) : (
            <div className="document-account-hint">با جستجوی نام یا وارد کردن کد، حساب را انتخاب کنید.</div>
          )}
        </div>
      </section>

      <section className="dashboard-panel document-entry-panel">
        <div className="document-meta-grid">
          <Field label="شماره سند">
            <input value={documentNumber} onChange={(event) => setDocumentNumber(event.target.value)} inputMode="numeric" />
          </Field>
          <Field label="نوع سند">
            <div className="document-segmented-control">
              <button type="button" className={documentNature === 'received' ? 'is-active received' : ''} onClick={() => setDocumentNature('received')}>سند دریافتی</button>
              <button type="button" className={documentNature === 'paid' ? 'is-active paid' : ''} onClick={() => setDocumentNature('paid')}>سند پرداختی</button>
            </div>
          </Field>
          <Field label="تاریخ سند (هجری شمسی)">
            <input value={documentDateJalali} onChange={(event) => setDocumentDateJalali(event.target.value)} placeholder="۱۴۰۵/۰۵/۲۲" dir="ltr" />
          </Field>
          <Field label="مبنای ثبت">
            <select value={balanceSource} onChange={(event) => setBalanceSource(event.target.value)}>
              <option value="current">حساب جاری</option>
              <option value="opening">مانده اول دوره</option>
              <option value="transfer">حواله / انتقال</option>
            </select>
          </Field>
        </div>

        <div className="document-tabs-wrap">
          <div className="document-tabs" role="tablist" aria-label="نوع عملیات سند">
            {documentTabs.map((tab, index) => (
              <button
                type="button"
                role="tab"
                aria-selected={documentTab === tab.id}
                className={documentTab === tab.id ? 'is-active' : ''}
                key={`${tab.id}-${tab.label}-${index}`}
                onClick={() => selectTab(tab.id)}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="document-operation-panel">
          <div className="document-operation-heading">
            <div>
              <p className="eyebrow">جزئیات عملیات</p>
              <h2>{documentTabs.find((tab) => tab.id === documentTab)?.label} · {documentNature === 'received' ? 'دریافت' : 'پرداخت'}</h2>
            </div>
            <Field label="نوع عملیات">
              <select value={documentSubType} onChange={(event) => setDocumentSubType(event.target.value)}>
                {operationOptions[documentTab].map(([value, label]) => <option key={value} value={value}>{label}</option>)}
              </select>
            </Field>
          </div>
          <OperationFields tab={documentTab} details={details} onChange={updateDetail} />
        </div>

        <div className="document-amount-panel">
          <div className="document-operation-heading">
            <div>
              <p className="eyebrow">اثر مستقیم بر دفتر</p>
              <h2>مبالغ و وزن‌های سند</h2>
            </div>
            <span className={`document-nature-badge ${documentNature}`}>
              {documentNature === 'received' ? 'دریافتی · افزایش مثبت' : 'پرداختی · اثر منفی'}
            </span>
          </div>
          <div className="document-amount-grid">
            {amountFields.map((field) => {
              const label = field.id === 'foreignAmount' ? foreignLabel : field.id === 'tertiaryAmount' ? tertiaryLabel : field.label;
              return (
                <Field key={field.id} label={`${label} (${field.unit})`}>
                  <input type="number" step="any" min="0" value={amounts[field.id]} onChange={(event) => updateAmount(field.id, event.target.value)} placeholder="۰" />
                </Field>
              );
            })}
          </div>
          <p className="document-amount-note">مقدار واردشده با توجه به دریافتی یا پرداختی بودن سند، با اثر صحیح در مانده طرف‌حساب ذخیره می‌شود.</p>
        </div>

        <div className="document-description-grid">
          <Field label="نحوه محاسبه">
            <select value={settlementMethod} onChange={(event) => setSettlementMethod(event.target.value)}>
              <option value="mixed">وزن و مبلغ</option>
              <option value="weight">وزنی</option>
              <option value="amount">مبلغ</option>
            </select>
          </Field>
          <Field label="توضیح سند" wide>
            <textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="توضیحی برای این سند بنویسید..." />
          </Field>
        </div>
      </section>

      <div className="document-actions">
        <button type="button" className="document-primary-button" onClick={() => void save(false)} disabled={saving}>
          {saving ? <LoaderCircle size={17} className="spin" /> : <FileCheck2 size={17} />}
          {saving ? 'در حال ثبت...' : 'ثبت کل سند'}
        </button>
        <button type="button" className="document-secondary-button" onClick={() => void save(true)} disabled={saving}>
          ثبت و سند بعدی
        </button>
      </div>
    </div>
  );
}

function OperationFields({
  tab,
  details,
  onChange,
}: {
  tab: DocumentTab;
  details: DetailState;
  onChange: (field: string, value: string) => void;
}) {
  const field = (name: string, label: string, type = 'text', placeholder = '') => (
    <Field key={name} label={label}>
      <input type={type} value={details[name] ?? ''} onChange={(event) => onChange(name, event.target.value)} placeholder={placeholder} />
    </Field>
  );

  if (tab === 'currency') {
    return (
      <div className="document-detail-grid">
        <Field label="نوع ارز">
          <select value={details.currency ?? ''} onChange={(event) => onChange('currency', event.target.value)}>
            {currencyOptions.map(([value, label]) => <option key={value} value={value}>{label}</option>)}
          </select>
        </Field>
        {field('currencySymbol', 'نماد ارز', 'text', 'مثلاً $')}
        {field('currencyRate', 'نرخ تبدیل', 'number', '۰')}
        {field('referenceNumber', 'شماره پیگیری')}
      </div>
    );
  }

  if (tab === 'check') {
    return (
      <div className="document-detail-grid">
        {field('checkNumber', 'شماره چک')}
        {field('bankName', 'نام بانک')}
        {field('checkAmount', 'مبلغ چک', 'number', '۰')}
        {field('checkDueDateJalali', 'تاریخ سررسید', 'text', '۱۴۰۵/۰۶/۰۱')}
        {field('checkOwner', 'صاحب چک')}
      </div>
    );
  }

  if (tab === 'goods') {
    return (
      <div className="document-detail-grid">
        {field('itemName', 'نام کالا')}
        {field('quantity', 'تعداد', 'number', '۰')}
        {field('itemUnit', 'واحد')}
        {field('unitPrice', 'قیمت واحد', 'number', '۰')}
        {field('referenceNumber', 'شماره فاکتور')}
      </div>
    );
  }

  if (tab === 'gold-sale' || tab === 'base' || tab === 'raw-gold') {
    return (
      <div className="document-detail-grid">
        {field('goldWeight', 'وزن کل (گرم)', 'number', '۰')}
        {field('purity', 'عیار', 'number', '۷۵۰')}
        {field('unitPrice', 'قیمت هر گرم', 'number', '۰')}
        {field('totalPrice', 'مبلغ کل', 'number', '۰')}
        {field('workmanship', 'اجرت / کارساخت', 'number', '۰')}
      </div>
    );
  }

  if (tab === 'stone' || tab === 'stone-main') {
    return (
      <div className="document-detail-grid">
        {field('stoneName', 'نام سنگ')}
        {field('stoneWeight', 'وزن سنگ', 'number', '۰')}
        {field('stonePrice', 'قیمت سنگ', 'number', '۰')}
        {field('stoneReference', 'شماره شناسایی')}
      </div>
    );
  }

  if (tab === 'coin') {
    return (
      <div className="document-detail-grid">
        {field('coinType', 'نوع سکه')}
        {field('coinCount', 'تعداد', 'number', '۰')}
        {field('coinPrice', 'قیمت واحد', 'number', '۰')}
        {field('referenceNumber', 'شماره پیگیری')}
      </div>
    );
  }

  if (tab === 'bank') {
    return (
      <div className="document-detail-grid">
        {field('bankName', 'نام بانک')}
        {field('accountNumber', 'شماره حساب')}
        {field('referenceNumber', 'شماره پیگیری')}
        {field('transferDateJalali', 'تاریخ انتقال', 'text', '۱۴۰۵/۰۵/۲۲')}
      </div>
    );
  }

  if (tab === 'expense' || tab === 'cash' || tab === 'cash-conversion') {
    return (
      <div className="document-detail-grid">
        {field('expenseTitle', 'عنوان')}
        {field('expenseAmount', 'مبلغ', 'number', '۰')}
        {field('referenceNumber', 'شماره پیگیری')}
      </div>
    );
  }

  if (tab === 'our-claim') {
    return (
      <div className="document-detail-grid">
        {field('claimWeight', 'طلب وزنی', 'number', '۰')}
        {field('claimFinancial', 'طلب مالی', 'number', '۰')}
        {field('claimDescription', 'شرح طلب')}
      </div>
    );
  }

  if (tab === 'workmanship' || tab === 'itak') {
    return (
      <div className="document-detail-grid">
        {field('laborWeight', 'وزن کار', 'number', '۰')}
        {field('laborRate', 'نرخ اجرت', 'number', '۰')}
        {field('laborAmount', 'مبلغ اجرت', 'number', '۰')}
      </div>
    );
  }

  return (
    <div className="document-detail-grid">
      {field('description', 'شرح عملیات')}
      {field('referenceNumber', 'کد رهگیری')}
      {field('location', 'محل / صندوق')}
    </div>
  );
}

function formatRegisteredAt(value: string) {
  return new Intl.DateTimeFormat('fa-IR', {
    dateStyle: 'short',
    timeStyle: 'short',
  }).format(new Date(value));
}

function Field({
  label,
  wide,
  children,
}: {
  label: string;
  wide?: boolean;
  children: React.ReactNode;
}) {
  return (
    <label className={`account-field ${wide ? 'document-field-wide' : ''}`}>
      <span>{label}</span>
      {children}
    </label>
  );
}
